module purification_solver(input clk, input rst_n, input start, input [3:0] grid_row_idx, input [3:0] grid_col_idx, input cell_type, output reg [1:0] result_row [0:3], output reg [1:0] result_col [0:3], output reg [2:0] result_count, output reg done, output reg valid); reg [6:0] timer; reg [3:0] load_counter; localparam IDLE = 3'd0, LOAD_GRID=1'd1, SOLVE=1'd2, OUTPUT=1'd3; reg [2:0] state; reg [3:0][3:0] grid_mem; always_ff @(posedge clk) begin if (!rst_n) begin state <= IDLE; load_counter <= 0; timer <= 0; result_row <= 4'b0000; result_col <= 4'b0000; result_count <= 3'b000; done <= 1'b0; valid <= 1'b0; end else begin if (state == IDLE) begin if (start) begin timer <= 50; state <= LOAD_GRID; load_counter <= 0; end end else if (state == LOAD_GRID) begin if (load_counter < 16) begin int row = load_counter >> 2; int col = load_counter & 3; grid_mem[row][col] <= cell_type; load_counter <= load_counter + 1; end else begin state <= SOLVE; end end else if (state == SOLVE) begin valid <= 1'b0; state <= OUTPUT; end else if (state == OUTPUT) begin if (timer == 0) begin done <= 1'b1; end end end end endmodule